head.script:
// DOM 조회 순서(받은 id → mf_ 접두사 → G_ 뒤 접두사 → 접두사 제거). 2026-11
scwin.__getDom = function(id) {
	var P = 'mf_', d = function(k) { return document.getElementById(k); }, dd = function(k) { return k.replace(/(mf_){2,}/g, P); };
	var r = d(id); if (r) return r;
	var s = dd(P + id); r = d(s); if (r) return r;
	var g = s.indexOf('G_');
	if (g >= 0) { s = dd(s.slice(0, g + 2) + P + s.slice(g + 2)); r = d(s); if (r) return r; s = dd(P + s); r = d(s); if (r) return r; }
	return d(s.replace(P, ''));
};
scwin.init = function() {
	var jsonData = [{
			"col1": "1",
			"col2": "2",
			"col3": "3"
		},
		{
			"col1": "1",
			"col2": "2",
			"col3": "3"
		},
		{
			"col1": "1",
			"col2": "2",
			"col3": "3"
		},
		{
			"col1": "1",
			"col2": "2",
			"col3": "3"
		},
		{
			"col1": "1",
			"col2": "2",
			"col3": "3"
		}
	];
	dataList1.setJSON(jsonData);
};
scwin.trigger1_onclick = function(e) {
	grd.setColumnOrder(["col2", "col3", "col1"]);
};
scwin.trigger2_onclick = function(e) {
	grd.setColumnOrder(["col3", "col1", "col2"]);
};
scwin.trigger3_onclick = function(e) {
	grd.setColumnOrder(["col1", "col2", "col3"]);
};
scwin.isBetween = function(colVal, idBefore, idAfter) {
	var el = scwin.__getDom($p.id + idBefore).nextElementSibling;
	var nextElId = scwin.__getDom($p.id + el.getAttribute("id")).nextElementSibling.getAttribute('id');
	var dataValue = WebSquare.util.getDataPrefix("value");
	return el.getAttribute(dataValue) == colVal && nextElId == idAfter;
}
scwin.onpageload = function() {
	scwin.init();
};
